import{_ as l,a0 as n,w as r,s as o,I as p,x as t,a1 as i,A as e,ao as k}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"如何在 Linux 中更新 Flatpak 软件包 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中更新 Flatpak 软件包 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中更新 Flatpak 软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中更新 Flatpak 软件包 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221210.2 ⭐️ How to Update Flatpak Packages in Linux","title":"如何在 Linux 中更新 Flatpak 软件包","tag":"202301","desc":""},"relativePath":"202301/20221210.2 ⭐️ How to Update Flatpak Packages in Linux.md","filePath":"[post].md"}'),d={name:"202301/20221210.2 ⭐️ How to Update Flatpak Packages in Linux.md"};function u(g,a,f,h,b,m){const s=n("Link");return r(),o("div",null,[a[20]||(a[20]=p("h1",{id:"如何在-linux-中更新-flatpak-软件包",tabindex:"-1"},[t("如何在 Linux 中更新 Flatpak 软件包 "),p("a",{class:"header-anchor",href:"#如何在-linux-中更新-flatpak-软件包","aria-label":"Permalink to “如何在 Linux 中更新 Flatpak 软件包”"},"​")],-1)),a[21]||(a[21]=p("p",null,[p("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/03/154131lop17rnnrkiprkl7.jpg",alt:""})],-1)),a[22]||(a[22]=p("p",null,"我相信几乎所有的 Linux 用户都会保持他们系统的更新。",-1)),p("p",null,[a[2]||(a[2]=t("但这种更新通常是针对默认的 ",-1)),i(s,{href:"https://itsfoss.com/package-manager/"},{default:e(()=>[...a[0]||(a[0]=[t("包管理器",-1)])]),_:1}),a[3]||(a[3]=t("。例如，",-1)),i(s,{href:"https://itsfoss.com/update-ubuntu/"},{default:e(()=>[...a[1]||(a[1]=[t("更新 Ubuntu",-1)])]),_:1}),a[4]||(a[4]=t(" 往往意味着更新所有的 APT 软件包。",-1))]),a[23]||(a[23]=k('<p>然而，还有其他的打包格式，如 Snap 和 Flatpak。Snap 应用程序会自动更新，但 Flatpak 不会。</p><p>那么你如何更新 Flatpak 软件包呢？好吧，你可以用这个命令来更新所有已安装和可更新的 Flatpak 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak update</span></span></code></pre></div><p>这很简单。但让我再讨论一下关于更新 Flatpak 的一些事情，比如说：</p><ul><li>更新所有或特定的 Flatpak 包</li><li>通过软件中心更新 Flatpak 包</li></ul><p>让我们先从终端的方法开始。</p><h3 id="方法-1-使用终端来更新-flatpak-包" tabindex="-1">方法 1：使用终端来更新 Flatpak 包 <a class="header-anchor" href="#方法-1-使用终端来更新-flatpak-包" aria-label="Permalink to “方法 1：使用终端来更新 Flatpak 包”">​</a></h3><p>首先让我从最实用的方法开始，你也应该从这个方法开始。</p><h4 id="更新每一个过时的-flatpak-包" tabindex="-1">更新每一个过时的 Flatpak 包 <a class="header-anchor" href="#更新每一个过时的-flatpak-包" aria-label="Permalink to “更新每一个过时的 Flatpak 包”">​</a></h4><p>更新现有的 Flatpak 包的整个目录是很容易的。</p><p>输入给定的命令，就可以得到过期包的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak update</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/12/3.-update-flatpak-packages-in-linux.png" alt="update flatpak packages in linux"></p><p>你只需输入 <code>Y</code> 并按下回车键，就能搞定每一个更新。</p><h4 id="更新特定的-flatpak-包" tabindex="-1">更新特定的 Flatpak 包 <a class="header-anchor" href="#更新特定的-flatpak-包" aria-label="Permalink to “更新特定的 Flatpak 包”">​</a></h4><p>要更新特定的软件包，你需要可以更新的软件包的列表。你用的是你之前看到的那个命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak update</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/12/3.-update-flatpak-packages-in-linux.png" alt="update flatpak packages in linux"></p><p>从输出中复制你要更新的软件包的名称。在以下命令中使用软件包的名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak update package_name</span></span></code></pre></div><p>例如，如果你想更新 Telegram，下面的命令可以完成这项工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak update org.telegram.desktop</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/12/4.-update-specific-package-in-flatpak.png" alt="update specific package in flatpak"></p><p>这就完成了。</p><h3 id="方法-2-从软件中心更新-flatpak-应用" tabindex="-1">方法 2：从软件中心更新 Flatpak 应用 <a class="header-anchor" href="#方法-2-从软件中心更新-flatpak-应用" aria-label="Permalink to “方法 2：从软件中心更新 Flatpak 应用”">​</a></h3><p>有 Flatpak 内置支持的发行版会在软件中心提供 Flatpak 应用的更新。Fedora 和 Linux Mint 就是这样的发行版。</p><p>但如果你使用的是 Ubuntu，你就需要在 GNOME 软件中心添加 Flatpak 支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-software-plugin-flatpak</span></span></code></pre></div><p>完成后，你将在 Ubuntu 中拥有两个软件中心。这是因为默认的软件中心不是 GNOME 的，而是 Snap Store。</p><p>从系统菜单中打开这个新的软件中心：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/12/1.-open-software-center-in-ubuntu.png" alt="open software center in ubuntu"></p><p>进入“<ruby>更新<rt>Update</rt></ruby>”页面，你会发现过时的软件包列表。这包括 APT 和 Flatpak 软件包。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/12/2.-update-flatpak-from-software-center.png" alt="update flatpak from software center"></p><p>在这里，你可以一次更新所有的软件包，或者你可以有选择地更新什么。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>许多 Linux 桌面用户往往忘记更新 Flatpak 软件包，因为它们不包括在定期的系统更新中。</p><p>由于 Flatpak 是一个沙盒式的打包解决方案，你可能不会面临任何与过时的软件包有关的问题，但你肯定会错过新的功能和修复。</p><p>这就是为什么我建议每隔几周运行一次 Flatpak 更新命令。</p><p>我希望你喜欢这个快速的 Flatpak 小技巧。</p><hr>',40)),p("p",null,[a[6]||(a[6]=t("via: ",-1)),i(s,{href:"https://itsfoss.com/update-flatpak/"},{default:e(()=>[...a[5]||(a[5]=[t("https://itsfoss.com/update-flatpak/",-1)])]),_:1})]),p("p",null,[a[11]||(a[11]=t("作者：",-1)),i(s,{href:"https://itsfoss.com/author/sagar/"},{default:e(()=>[...a[7]||(a[7]=[t("Sagar Sharma",-1)])]),_:1}),a[12]||(a[12]=t(" 选题：",-1)),i(s,{href:"https://github.com/lkxed"},{default:e(()=>[...a[8]||(a[8]=[t("lkxed",-1)])]),_:1}),a[13]||(a[13]=t(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:e(()=>[...a[9]||(a[9]=[t("geekpi",-1)])]),_:1}),a[14]||(a[14]=t(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:e(()=>[...a[10]||(a[10]=[t("wxy",-1)])]),_:1})]),p("p",null,[a[17]||(a[17]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[15]||(a[15]=[t("LCTT",-1)])]),_:1}),a[18]||(a[18]=t(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:e(()=>[...a[16]||(a[16]=[t("Linux中国",-1)])]),_:1}),a[19]||(a[19]=t(" 荣誉推出",-1))])])}const C=l(d,[["render",u]]);export{F as __pageData,C as default};
